: [{"type": "text", "text": "路程不等时误用平均速度公式"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "去程和回程的时间搞混"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "往返行程的平均速度公式是高频考点。记住v_avg = 2v1v2/(v1+v2)，不要用算术平均。"}]}]}]}$$ AS jsonb), NULL, '数量关系-行程问题-往返行程的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "行程问题", "往返行程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_travel_roundtrip", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
